    void drawRoundedRectangleWithDashedLine() throws Exception {
        final Path dst = Paths.get("target/drawStroke.ofd");
        try (OFDGraphicsDocument doc = new OFDGraphicsDocument(dst)) {
            // Define page size: width=500, height=500
            ST_Box pageSize = new ST_Box(0, 0, 500, 500);
            // Create an XML element for CT_PageArea
            Element pageAreaElement = DocumentHelper.createElement("PageArea");
            // Assume CT_PageArea has a method to set the boundary
            CT_PageArea pageArea = new CT_PageArea(pageAreaElement);
            pageArea.setBoundary(pageSize);
            OFDPageGraphics2D g = doc.newPage(pageArea);

            // Set dashed stroke with pattern [10, 5]
