            g.setStroke(new BasicStroke(
                2.0f, 
                BasicStroke.CAP_BUTT, 
                BasicStroke.JOIN_MITER, 
                10.0f, 
                dashPattern, 
                0.0f
            ));

            // Create a rounded rectangle with specified dimensions and corner radius
            RoundRectangle2D roundedRect = new RoundRectangle2D.Double(
                50, 50, 400, 400, 20, 20
            );

            // Draw the rounded rectangle
            g.draw(roundedRect);
        }
        System.out.println(">> " + dst.toAbsolutePath());
    }

}

