import java.awt.geom.AffineTransform;
import java.awt.image.BufferedImage;
import java.nio.file.Path;
import java.nio.file.Paths;

import static org.junit.jupiter.api.Assertions.assertTrue;

class OFDPageGraphics2DTest {

    @Test
    void drawImageWithCTM() throws Exception {
        // Define the output OFD file path
        final Path dst = Paths.get("target/drawImageWithCTM.ofd");

        // Create a new OFD graphics document
        try (OFDGraphicsDocument doc = new OFDGraphicsDocument(dst)) {
            // Initialize a new page with specified dimensions
            OFDPageGraphics2D g = doc.newPage(1000, 800);

            // Load the image from the specified file
            Path file = Paths.get("src/test/resources", "eg_tulip.jpg");
            BufferedImage img = ImageIO.read(file.toFile());

            // Create an AffineTransform for translation and rotation
            AffineTransform at = new AffineTransform();
            at.translate(400, 0); // Move the image 400 units to the right
            at.rotate(Math.toRadians(90), img.getWidth() / 2.0, img.getHeight() / 2.0); // Rotate 90 degrees

            // Apply the transformation to the graphics context
            g.setTransform(at);

            // Draw the transformed image at the origin after transformation
            g.drawImage(img, null, 0, 0);
        }

        // Verify that the OFD file was created successfully
        Path absolutePath = dst.toAbsolutePath();
        assertTrue(dst.toFile().exists(), "OFD file should be created.");

        // Output the absolute path of the created OFD file
        System.out.println(">> " + absolutePath);
    }
}

