    void rotateAndTranslate() throws Exception {
        // Define the output file path
        final Path dst = Paths.get("target/translateRotate.ofd");

        // Create the OFD graphics document
        try (OFDGraphicsDocument doc = new OFDGraphicsDocument(dst)) {
            // Create a new page with specified dimensions
            OFDPageGraphics2D g = doc.newPage(300, 300);

            // Set the drawing color to red
            g.setColor(Color.red);

            // Translate the origin to (100, 100)
            g.translate(100, 100);

            // Rotate the graphics context by 45 degrees
            g.rotate(Math.toRadians(45));

            // Draw a filled rectangle centered at the translated origin
            g.fillRect(-50, -50, 100, 100);
        }

        // Print the absolute path of the created file
        System.out.println(">> " + dst.toAbsolutePath());

        // Assert that the output file has been created
        assertTrue(dst.toFile().exists(), "Output file translateRotate.ofd should be created in the target directory.");
    }

}

