            AffineTransform initialTransform = new AffineTransform();
            initialTransform.rotate(Math.toRadians(45), 250, 250);
            initialTransform.translate(50, 50);
            g.setTransform(initialTransform);
            g.setColor(Color.RED);
            g.fillRect(200, 200, 100, 100); // Draw red rectangle

            // Reset transformation to identity
            AffineTransform resetTransform = new AffineTransform();
            g.setTransform(resetTransform);

            // Apply translation by (100, 100) and then rotate by 30 degrees
            AffineTransform secondTransform = new AffineTransform();
            secondTransform.translate(100, 100);
            secondTransform.rotate(Math.toRadians(30));
            g.setTransform(secondTransform);
            g.setColor(Color.BLUE);
            g.fillRect(300, 300, 100, 100); // Draw blue rectangle
        }

        // Assert that the output OFD file was created successfully
        assertTrue(Files.exists(dst), "Output OFD file should be created successfully.");
    }
