    public void setEnableZeroPrefix(boolean enableZeroPrefix) {
        this.enableZeroPrefix = enableZeroPrefix;
    }

    /**
     * 是否启用0前缀
     *
     * @return true - 启用0前缀
     */
    public boolean isEnableZeroPrefix() {
        return enableZeroPrefix;
    }
